import{c as l,Z as o,Q as r,j as n,m as s,o as t}from"./chunks/framework.DOi4mjdC.js";const f=JSON.parse('{"title":"水仙子·咏江南","description":"","frontmatter":{"title":"水仙子·咏江南","author":"张养浩","dynasty":"元"},"headers":[],"relativePath":"books/shici/yuanqu/12.md","filePath":"books/shici/yuanqu/12.md"}'),h={name:"books/shici/yuanqu/12.md"};function u(p,a,c,d,_,m){const e=o("PoemAuthor"),i=o("PoemNav");return r(),n("div",null,[a[0]||(a[0]=s('<h1 id="水仙子·咏江南" tabindex="-1">水仙子·咏江南 <a class="header-anchor" href="#水仙子·咏江南" aria-label="Permalink to &quot;水仙子·咏江南&quot;">​</a></h1><p><strong>[元] <a href="/authors/zhangyanghao.html">张养浩</a></strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>一江烟水照晴岚，两岸人家接画檐，芰荷丛一段秋光淡。看沙鸥舞再三，卷香风十里珠帘。画船儿天边至，酒旗儿风外飐。爱杀江南！</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>水仙子：曲牌名</li><li>晴岚：晴日山间的雾气</li><li>画檐：装饰华丽的屋檐</li><li>芰荷：菱叶和荷叶</li><li>秋光淡：秋天的光线柔和淡雅</li><li>沙鸥：水鸟</li><li>卷香风：带着香气的风</li><li>珠帘：珍珠装饰的帘子</li><li>画船：装饰华丽的船</li><li>酒旗：酒店的旗帜</li><li>风外飐：在风中飘动</li><li>爱杀：爱极了</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>一江烟水映照着晴日的山岚，两岸的人家连接着华丽的屋檐，菱叶荷叶丛中透出一段淡雅的秋光。看沙鸥翩翩起舞，带着香气的风卷起十里的珠帘。装饰华丽的船从天边驶来，酒店的旗帜在风中飘动。爱极了这江南！</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>这首小令是张养浩的代表作，描绘了江南水乡的美丽景色，表达了作者对江南的赞美之情。</p><p>&quot;一江烟水照晴岚，两岸人家接画檐&quot;，开篇就勾勒出一幅江南水乡的全景图。烟水、晴岚、人家、画檐，将江南的秀美描绘得淋漓尽致。</p><p>&quot;芰荷丛一段秋光淡&quot;，写秋天的江南。菱叶荷叶丛中，透出淡雅的秋光，将江南的秋景描绘得清新脱俗。</p><p>&quot;看沙鸥舞再三，卷香风十里珠帘&quot;，写江南的动态美。沙鸥起舞，香风卷帘，将江南的生机和灵动表现得生动传神。</p><p>&quot;画船儿天边至，酒旗儿风外飐&quot;，写江南的人文景观。画船从远处驶来，酒旗在风中飘动，将江南的繁华和诗意融为一体。</p><p>&quot;爱杀江南！&quot;，以感叹作结，直抒胸臆，表达了作者对江南的无限热爱。</p><p>全曲语言清丽，意境优美，将江南水乡的自然美和人文美完美融合，是咏江南的千古名篇。</p>',16)),t(e,{name:"张养浩",years:"1270年－1329年",desc:"字希孟，号云庄，元代著名散曲家。其散曲多写隐逸生活，风格清新自然，也有关心民生疾苦之作。",link:"/authors/zhangyanghao"}),t(i)])}const b=l(h,[["render",u]]);export{f as __pageData,b as default};
